Adding clause directions barely helps layers 7 and 9 in the trained phrasing (L7.H0 question attention 0.08 → 0.30 on dev TEST but only 0.17 on new-kind facts), whereas the current edit's trigger handling gets 0.43–0.44 there. So in the trained phrasing the query itself is different at the reply positions (the "guess present" trigger in the residual), and that must be handled on the input side. I'll use the same oblique idea on the query input: estimate the with-guess minus no-guess difference of the normalised residual at the decision position (per-phrasing means), and remove it with a projector whose read-off vector is orthogonal to the residuals seen at reply positions without a guess, so no-guess queries are unchanged by construction. I'll evaluate the combination (input-side trigger removal + output-side guess-key removal) analytically for layers 7, 9, 10 and 12 against the current edit on held-out facts.

```python
# Input-side oblique trigger removal + output-side oblique guess-key removal; held-out analytic eval for L7, L9, L10, L12
def uin(l,s,pos): 
    L=LP(l); return xnorm(Xof(s,l)[pos:pos+1],L['gin'])[0]
def trig_design(l, fit_pairs, fit_n, r_n, offs=(0,)):
    groups={}; 
    for sT,sN in fit_pairs:
        for o in offs: groups.setdefault(sT['ph'],[]).append(uin(l,sT,sT['p']-o)-uin(l,sN,sN['p']-o))
    Dm=torch.stack([torch.stack(v).mean(0) for v in groups.values()])
    Un=torch.stack([uin(l,s,s['p']-o) for s in fit_n for o in (0,1,2)])
    U,Sg,Vt=torch.linalg.svd(Un,full_matrices=False); R=Vt[:r_n]
    A=Dm-(Dm@R.T)@R
    return Dm,A
def trig_W(Wq, heads, Dm, A):
    M=torch.linalg.inv(A@Dm.T); W_=Wq.clone()
    for h in heads:
        blk=W_[h*256:(h+1)*256]; W_[h*256:(h+1)*256]=blk-(blk@Dm.T)@M@A
    return W_
def pairs(src,fids,phs):
    out=[]
    for s in sel(src,fids,phs):
        n=[x for x in SAMP if x['src']==src and x['fid']==s['fid'] and x['ph']=='N'][0]; out.append((s,n))
    return out
fitPairs=pairs('D',FIT,'T')+pairs('G',range(6),'ABD'); fitN2=sel('D',FIT,'N')+sel('G',range(6),'N')
def show_combo(l, r=30, r_n=30):
    L=LP(l); Dl,S=design2(l,fitG,fitN,r,0); Dm,A=trig_design(l,fitPairs,fitN2,r_n)
    print(f'--- L{l}: trigger dirs norm', Dm.norm(dim=1).numpy().round(2), 'frac outside N-subspace', ((A.norm(dim=1)/Dm.norm(dim=1))**2).numpy().round(2), 'cos between phrasing dirs (T vs others)', torch.nn.functional.cosine_similarity(Dm[0:1],Dm[1:]).numpy().round(2))
