    U,S,Vt=torch.linalg.svd(D,full_matrices=False); return (S[:k,None]*Vt[:k])
def build_V3(kg=2, kt=2, r=30, r_n=30, trig_layers=(7,9), heads=HEADS, l5_T_only=True):
