    return C/len(samples), (d/max(nd,1))
fit=lambda s: (s['fact']>=1000) or (s['fact']%2==0)
FITS={g:[s for s in SZ+SD if fit(s) and s['grp'] in gs] for g,gs in {'N':['N'],'T':['T'],'E':['E'],'GF':['H','H3','devH','devH2']}.items()}
print({g:len(v) for g,v in FITS.items()})
ST={h:{g:stats(FITS[g],h) for g in FITS} for h in range(4)}
def design_aw(lam,wts=dict(N=1,T=1,E=1,GF=1),zero=('T','E','null')):
    W=W_V3.clone().double().view(4,256,640); Bs=[]
    for h in range(4):
        C=sum(wts[g]*ST[h][g][0] for g in wts); C=C+lam*torch.trace(C)/256*torch.eye(256,dtype=torch.double)
        d=ST[h]['GF'][1]
        G=[d]+[ST[h][g][1] for g in zero if g in ('T','E')]+([torch.tensor(NULL12[h][k]).double() for k in range(2)] if 'null' in zero else [])
